const rows = $json.invoices ?? [];

function parseAmount(value) {
  if (value === null || value === undefined || value === '') return null;
  let s = String(value).replace(/\s/g,'').replace(/EUR/gi,'').replace(/€/g,'');
  if (/^\d{1,3}(\.\d{3})+,\d{2}$/.test(s)) s = s.replace(/\./g,'').replace(',','.');
  else if (/^\d+,\d{1,2}$/.test(s)) s = s.replace(',','.');
  const n = Number(s);
  return Number.isFinite(n) ? Math.round(n * 100) / 100 : null;
}

function parseDate(value) {
  if (!value) return null;
  const s = String(value).trim();
  let m;
  if ((m = s.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})$/))) {
    return new Date(Date.UTC(Number(m[3]), Number(m[2])-1, Number(m[1]))).toISOString().slice(0,10);
  }
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  return null;
}

function normalizeSupplier(value) {
  const raw = String(value ?? '').trim().replace(/\s+/g,' ');
  const key = raw.toLowerCase()
    .replace(/ü/g,'u').replace(/ö/g,'o').replace(/ä/g,'a').replace(/ß/g,'ss')
    .replace(/[^a-z0-9]/g,'');
  const aliases = {
    'exampleofficegmbh':'Example Office GmbH',
    'exampleofficegmbh':'Example Office GmbH',
    'exampleitgmbh':'Example IT GmbH',
    'exampledevicesgmbh':'Example Devices GmbH',
    'examplelogisticsgmbh':'Example Logistics GmbH',
    'exampleprintgmbh':'Example Print GmbH'
  };
  return aliases[key] ?? raw;
}

function normalizeInvoiceNumber(value) {
  const s = String(value ?? '').trim().toUpperCase();
  return s ? s.replace(/\s+/g,'-') : '';
}

function paymentDays(value) {
  const s = String(value ?? '').trim().toLowerCase();
  if (s === 'sofort') return 0;
  const m = s.match(/\d+/);
  return m ? Number(m[0]) : null;
}

function normalizeCostCenter(value) {
  const s = String(value ?? '').trim().toLowerCase();
  const map = {'verw.':'Verwaltung','verwaltung':'Verwaltung','it':'IT','lager':'Lager'};
  return map[s] ?? (s ? s.charAt(0).toUpperCase()+s.slice(1) : '');
}

function normalizeStatus(value) {
  const s = String(value ?? '').trim().toLowerCase();
  const map = {'offen':'Offen','bezahlt':'Bezahlt','storniert':'Storniert'};
  return map[s] ?? (s ? s.charAt(0).toUpperCase()+s.slice(1) : '');
}

function dueDate(invoiceDate, days) {
  if (!invoiceDate || days === null) return null;
  const d = new Date(invoiceDate+'T00:00:00Z');
  d.setUTCDate(d.getUTCDate()+days);
  return d.toISOString().slice(0,10);
}

const cleaned = rows.map((row,index) => {
  const invoiceDate = parseDate(row.invoice_date);
  const gross = parseAmount(row.gross);
  const days = paymentDays(row.payment_terms);
  const invoiceNumber = normalizeInvoiceNumber(row.invoice_number);
  const issues = [];
  if (!invoiceDate) issues.push('Rechnungsdatum fehlt/ungültig');
  if (!invoiceNumber) issues.push('Rechnungsnummer fehlt');
  if (gross === null) issues.push('Bruttobetrag fehlt/ungültig');
  if (!row.cost_center) issues.push('Kostenstelle fehlt');

  return {
    row_id:index+1,
    supplier:normalizeSupplier(row.supplier),
    invoice_date:invoiceDate,
    invoice_number:invoiceNumber,
    gross,
    payment_days:days,
    due_date:dueDate(invoiceDate,days),
    cost_center:normalizeCostCenter(row.cost_center),
    status:normalizeStatus(row.status),
    duplicate:false,
    issues
  };
});

const counts = new Map();
for (const r of cleaned) {
  if (!r.invoice_number || r.gross === null) continue;
  const key = `${r.invoice_number}|${r.gross.toFixed(2)}`;
  counts.set(key,(counts.get(key) ?? 0)+1);
}
for (const r of cleaned) {
  if (!r.invoice_number || r.gross === null) continue;
  const key = `${r.invoice_number}|${r.gross.toFixed(2)}`;
  if ((counts.get(key) ?? 0) > 1) {
    r.duplicate = true;
    r.issues.push('Mögliche Dublette');
  }
}

return [{json:{cleaned}}];

const rows = $json.cleaned ?? [];
const reviewRows = rows.filter(r => r.issues.length > 0);
const duplicateRows = rows.filter(r => r.duplicate);
const validGross = rows.filter(r => typeof r.gross === 'number');
const grossTotal = Math.round(validGross.reduce((sum,r)=>sum+r.gross,0)*100)/100;
const uniqueIssueTypes = [...new Set(reviewRows.flatMap(r=>r.issues))];
const status = reviewRows.length === 0 ? 'OK' : 'REVIEW_REQUIRED';

return [{
  json:{
    status,
    summary:{
      records:rows.length,
      records_with_review:reviewRows.length,
      possible_duplicates:duplicateRows.length,
      gross_total:grossTotal,
      issue_types:uniqueIssueTypes
    },
    notification_message: status === 'OK'
      ? `Datenprüfung abgeschlossen: ${rows.length} Datensätze, keine Prüfhinweise.`
      : `Datenprüfung abgeschlossen: ${rows.length} Datensätze, ${reviewRows.length} mit Prüfhinweis, ${duplicateRows.length} mögliche Dubletten.`,
    cleaned_rows:rows,
    next_step:status === 'OK'
      ? 'Automatische Weiterverarbeitung möglich.'
      : 'Prüffälle vor Weiterverarbeitung kontrollieren.'
  }
}];
